(169,18,'_yoast_wpseo_title','İzmir Mobil Oto Bakım ve Detaylı Temizlik | MOBİLİZMİR'),
(170,18,'_yoast_wpseo_metadesc','İzmir genelinde bulunduğunuz yere gelerek boyasız göçük düzeltme, pasta cila, far temizliği ve koltuk yıkama hizmetleri sunuyoruz. Hemen randevu alın!'),
(171,18,'_yoast_wpseo_opengraph-image','http://localhost:8000/wp-content/uploads/2026/09/mobilizmir-logo.svg'),
(172,49,'_yoast_wpseo_title','Hakkımızda | MOBİLİZMİR - Premium Araç Bakım'),
(173,49,'_yoast_wpseo_metadesc','Mobilİzmir, zamanınızı çalmadan evinize veya iş yerinize gelerek profesyonel araç bakım hizmetleri sunan İzmir merkezli mobil servisinizdir.'),
(174,49,'_yoast_wpseo_opengraph-image','http://localhost:8000/wp-content/uploads/2026/09/mobilizmir-logo.svg'),
(175,5,'_yoast_wpseo_title','Hizmetlerimiz | İzmir Mobil Oto Kuaför'),
(176,5,'_yoast_wpseo_metadesc','Pasta cila, koltuk yıkama, far parlatma, göçük düzeltme ve periyodik araç bakım hizmetlerimizle aracınızı ilk günkü ihtişamına kavuşturuyoruz.'),
(177,5,'_yoast_wpseo_opengraph-image','http://localhost:8000/wp-content/uploads/2026/09/mobilizmir-logo.svg'),
(178,19,'_yoast_wpseo_title','Mobil Koltuk Yıkama ve Detaylı İç Temizlik | İzmir'),
(179,19,'_yoast_wpseo_metadesc','Araç koltuklarınızdaki inatçı leke ve kokuları profesyonel makinelerle yerinde temizliyoruz. İzmir içi hızlı ve derinlemesine koltuk yıkama hizmeti.'),
(180,19,'_yoast_wpseo_opengraph-image','http://localhost:8000/wp-content/uploads/2026/09/mobilizmir-logo.svg'),
(181,20,'_yoast_wpseo_title','Pasta Cila ve Çizik Giderme | MOBİLİZMİR'),
(182,20,'_yoast_wpseo_metadesc','Güneş yanıkları, kılcal çizikler ve matlaşan boyanız için profesyonel pasta cila hizmeti. Aracınıza showroom parlaklığını yerinde kazandırıyoruz.'),
(183,20,'_yoast_wpseo_opengraph-image','http://localhost:8000/wp-content/uploads/2026/09/mobilizmir-logo.svg'),
(184,21,'_yoast_wpseo_title','Garantili Far Temizliği ve Parlatma | İzmir'),
(185,21,'_yoast_wpseo_metadesc','Sararmış ve matlaşmış farlarınızı zımpara ve özel kimyasallarla ilk günkü şeffaflığına kavuşturuyoruz. Görüş mesafenizi ve güvenliğinizi artırın.'),
(186,21,'_yoast_wpseo_opengraph-image','http://localhost:8000/wp-content/uploads/2026/09/mobilizmir-logo.svg'),
