(199,7,'_yoast_wpseo_title','İletişim ve WhatsApp Randevu | MOBİLİZMİR'),
(200,7,'_yoast_wpseo_metadesc','Mobilİzmir ile iletişime geçin. WhatsApp üzerinden hemen fiyat teklifi alın veya adresinize mobil servis çağırın. İzmir geneli yerinde hizmet.'),
