(21,'http://localhost:8000/boyasiz-gocuk-duzeltme/','45:a2e71f35c1b87a9bd266a90dbc975dca',22,'post','page',0,0,'Boyasız Göçük Düzeltme (PDR) | MOBİLİZMİR','Dolu hasarı, otopark göçükleri ve ufak kaporta eziklerini aracınızın orijinalliğini ve boyasını bozmadan PDR tekniğiyle yerinde düzeltiyoruz.','Boyasız Göçük Düzeltme','publish',NULL,0,NULL,NULL,NULL,NULL,NULL,0,0,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'http://localhost:8000/wp-content/uploads/2026/09/mobilizmir-logo.svg',NULL,'set-by-user',NULL,0,NULL,NULL,'2026-09-07 10:27:06','2026-09-07 10:55:32',1,NULL,NULL,NULL,NULL,0,NULL,2,'2026-09-07 10:55:32','2026-09-07 07:42:28',0,0,0),
